import { slardar } from "@lark-apaas/internal-slardar";
import { getHmrApi } from "../utils/hmr-api.js";
import { submitPostMessage } from "../utils/postMessage.js";
import { levelSchema } from "./log-types.js";
import { logger } from "./logger.js";
let devServerDisconnectInfo = null;
let retryCount = 0;
function processDevServerLog(log) {
    if (!log) return;
    const devFlag = log.includes('[webpack-dev-server]');
    if (devFlag && log.includes('Disconnected')) {
        const time = Date.now();
        devServerDisconnectInfo = {
            time
        };
        submitPostMessage({
            type: 'DevServerMessage',
            data: {
                type: 'devServer-status',
                status: 'disconnected'
            }
        });
        slardar.sendEvent({
            name: 'sandbox-devServer',
            metrics: {
                time
            },
            categories: {
                type: 'disconnected'
            }
        });
        return;
    }
    if (!devServerDisconnectInfo) return;
    if (devFlag && log.includes('Trying to reconnect')) {
        if (retryCount) slardar.sendEvent({
            name: 'sandbox-devServer',
            metrics: {
                retryCount: retryCount + 1
            },
            categories: {
                type: 'reconnect-failed'
            }
        });
        retryCount++;
        return;
    }
    const hmrFlag = log.includes('[HMR]');
    if (hmrFlag || devFlag && (log.includes('Socket connected') || log.includes('App updated') || log.includes('App hot update'))) {
        submitPostMessage({
            type: 'DevServerMessage',
            data: {
                type: 'devServer-status',
                status: 'connected'
            }
        });
        const startTime = devServerDisconnectInfo.time;
        const duration = Date.now() - startTime;
        devServerDisconnectInfo = null;
        slardar.sendEvent({
            name: 'sandbox-devServer',
            metrics: {
                startTime,
                duration
            },
            categories: {
                type: 'devServer-reconnected'
            }
        });
    }
}
function listenModuleHmr() {
    const hmr = getHmrApi();
    if (hmr) {
        hmr.onSuccess(()=>{
            submitPostMessage({
                type: 'DevServerMessage',
                data: {
                    type: 'devServer-status',
                    status: 'hmr-apply-success'
                }
            });
        });
        hmr.onError((error)=>{
            console.warn('hmr apply failed', error);
            slardar.sendEvent({
                name: 'sandbox-devServer',
                categories: {
                    type: 'hmr-apply-failed',
                    error: String(error)
                }
            });
        });
    }
}
function interceptErrors() {
    window.addEventListener('error', (event)=>{
        logger.error(event.error);
    });
    window.addEventListener('unhandledrejection', (event)=>{
        logger.error(event.reason);
    });
    listenModuleHmr();
    const PROXY_CONSOLE_METHOD = [
        'log',
        'info',
        'warn',
        'error'
    ];
    PROXY_CONSOLE_METHOD.forEach((method)=>{
        const originalMethod = window.console[method];
        window.console[method] = (...args)=>{
            originalMethod(...args);
            const level = 'log' === method ? 'info' : method;
            const log = args[0];
            if ('string' == typeof log) processDevServerLog(log);
            if ('string' == typeof log && log.startsWith('[Dataloom]') && levelSchema.safeParse(level).success) {
                logger.log({
                    level: level,
                    args
                });
                submitPostMessage({
                    type: 'Console',
                    method,
                    data: args
                });
            }
        };
    });
}
export { interceptErrors };
